// runnable-embeds-freshness.ts — every generated region in a host runnable is a fresh derivation of its
// authorities (phase 37, plan 37-03, SPLIT-05).
//
// A host runnable carries copies of the board grammar, the non-blocking reader, the budget rules and the budget
// numbers, generated by scripts/generate-runnable-embeds.ts. A copy is only worth anything while it equals its
// authority, so this gate re-derives every region and refuses any difference, including a one-character hand
// edit inside a region and an authority that moved underneath it. The same contract every other freshness gate
// in this repository carries. Wired in .github/workflows/ci.yml and asserted at both ends by
// scripts/generate-runnable-embeds.test.ts.

import { isEntrypoint } from "./is-entry.js";
import { EMBED_SPECS, rewriteRunnable } from "./generate-runnable-embeds.js";

const isEntry = isEntrypoint(import.meta.url);

if (isEntry) {
  let target = "";
  try {
    const stale: string[] = [];
    for (const spec of EMBED_SPECS) {
      target = spec.target;
      if (rewriteRunnable(spec).changed) stale.push(spec.target);
    }
    if (stale.length > 0) {
      console.log(
        `Runnable-embeds freshness check FAILED: ${stale.join(", ")}: the generated region is not a fresh ` +
          "derivation of its authorities. Either a region was edited by hand, or an authority changed without " +
          "the region moving. Do not edit the region by hand. Remedy: npm run generate:runnable-embeds, then " +
          "commit the runnable's .ts and .js together.",
      );
      process.exit(1);
    }
    console.log(`Runnable embeds fresh: ${EMBED_SPECS.length} target(s) match a fresh derivation.`);
    process.exit(0);
  } catch (e) {
    console.log(
      `Runnable-embeds freshness check FAILED: ${target}: ${(e as Error).message} ` +
        "Remedy: npm run generate:runnable-embeds.",
    );
    process.exit(1);
  }
}
